package vn.gastroai.be.application.auth; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; @Service public class EmailVerificationService { private final JavaMailSender mail; private final String from,base; public EmailVerificationService(JavaMailSender m,@Value("${app.mail.from}")String f,@Value("${app.mail.verification-base-url}")String b){mail=m;from=f;base=b;} public void send(String to,String token){SimpleMailMessage x=new SimpleMailMessage();x.setFrom(from);x.setTo(to);x.setSubject("Xac thuc tai khoan GastroAI");x.setText("Xac thuc tai khoan: "+base+"?token="+token+"\nLien ket co hieu luc 24 gio.");mail.send(x);} }
